def fact(x):
    if x==0:
        return 1
    else:
        return x*fact(x-1)
def puiss(x,y):
    if y==0:
        return 1
    else:
        return x*puiss(x,y-1)
def exp(x,eps):
    s1=1
    s2=s1+x
    i=2
    while abs(s2-s1)>eps:
        s1=s2
        s2=s1+puiss(x,i)/fact(i)
        i=i+1
    return s2
